package dev.classrevive.cli;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.io.*;
import java.lang.reflect.Member;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.zip.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Runs the CLI over jars produced by a real ProGuard 7.10.0 run (benchmarks/obfuscated/proguard8, regenerated by
 * {@code gradlew regenerateObfuscatedFixtures}). Renamed classes are only defined and linked, never initialized or run.
 */
class ProguardFixtureTest {
    static final Path FIXTURES = Path.of(System.getProperty("classrevive.obfuscatedFixtures", "missing"));
    @TempDir Path directory;
    ByteArrayOutputStream output = new ByteArrayOutputStream();
    ByteArrayOutputStream errors = new ByteArrayOutputStream();
    int run(String... args) { return Main.run(args, new PrintStream(output), new PrintStream(errors)); }

    static Map<String,byte[]> classes(Path jar) throws IOException {
        var result = new TreeMap<String,byte[]>();
        try (var zip = new ZipFile(jar.toFile())) {
            for (var entries = zip.entries(); entries.hasMoreElements(); ) {
                var entry = entries.nextElement();
                if (entry.getName().endsWith(".class"))
                    result.put(entry.getName().substring(0, entry.getName().length() - 6).replace('/', '.'), zip.getInputStream(entry).readAllBytes());
            }
        }
        return result;
    }

    /** Defines every class of the jar in an isolated loader and links it, which runs the JVM verifier; nothing is initialized. */
    static Map<String,Class<?>> link(Map<String,byte[]> bytes) throws Exception {
        var loader = new ClassLoader(null) {
            @Override protected Class<?> findClass(String name) throws ClassNotFoundException {
                byte[] value = bytes.get(name); if (value == null) throw new ClassNotFoundException(name);
                return defineClass(name, value, 0, value.length);
            }
        };
        var result = new TreeMap<String,Class<?>>();
        for (String name : bytes.keySet()) {
            var type = Class.forName(name, false, loader);
            type.getDeclaredMethods(); type.getDeclaredFields(); type.getDeclaredConstructors();
            result.put(name, type);
        }
        return result;
    }

    static Set<String> names(Member[] members) {
        var result = new TreeSet<String>(); for (var member : members) result.add(member.getName()); return result;
    }

    static String sha256(Path file) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file)));
    }

    Path rename(String variant) throws Exception {
        Path jar = FIXTURES.resolve(variant + ".jar"), mapping = FIXTURES.resolve(variant + ".mapping.txt");
        assertTrue(Files.isRegularFile(jar) && Files.isRegularFile(mapping), "fixture missing under " + FIXTURES);
        String before = sha256(jar);
        Path result = directory.resolve(variant + "-renamed");
        assertEquals(0, run("rename", jar.toString(), "--proguard-mapping", mapping.toString(), "--output", result.toString()), errors.toString());
        assertEquals(before, sha256(jar));
        return result;
    }

    @Test void obfuscatedInputUsesProguardNamesAndPassesVerification() throws Exception {
        for (String variant : List.of("obf8", "obf8-opt")) {
            var bytes = classes(FIXTURES.resolve(variant + ".jar"));
            assertEquals(Set.of("fixtures.obf.Main", "fixtures.obf.a", "fixtures.obf.b", "fixtures.obf.c"), bytes.keySet());
            assertDoesNotThrow(() -> link(bytes), variant);
        }
    }

    @Test void restoresSamePackageClassesAndPrivateMembersFromUnoptimizedProguardOutput() throws Exception {
        Path result = rename("obf8");
        String report = Files.readString(result.resolve("rename.json"));
        assertTrue(report.contains("\"mapping\":\"proguard\""), report);
        assertTrue(report.contains("\"forward\":{\"fixtures/obf/a\":\"fixtures/obf/Ledger\",\"fixtures/obf/b\":\"fixtures/obf/Ledger$Entry\",\"fixtures/obf/c\":\"fixtures/obf/Vault\"}"), report);
        assertTrue(report.contains("\"applicable_classes\":3,\"applicable_members\":9,\"inline_frames_ignored\":0"), report);
        assertTrue(report.contains("\"skipped\":{\"NOT_PRIVATE\":5,\"SERIALIZATION_MEMBER\":2}"), report);
        assertTrue(report.contains("{\"reason\":\"SERIALIZATION_MEMBER\",\"rule\":\"field fixtures/obf/a#a -> serialVersionUID\"}"), report);
        assertTrue(report.contains("{\"reason\":\"SERIALIZATION_MEMBER\",\"rule\":\"method fixtures/obf/a#a -> writeObject\"}"), report);
        assertTrue(report.contains("\"members_renamed\":9"), report);

        var renamed = classes(result.resolve("renamed.jar"));
        assertEquals(Set.of("fixtures.obf.Main", "fixtures.obf.Ledger", "fixtures.obf.Ledger$Entry", "fixtures.obf.Vault"), renamed.keySet());
        var types = link(renamed);
        var ledger = types.get("fixtures.obf.Ledger");
        // serialVersionUID keeps its obfuscated name "a": a serialization member is never renamed.
        assertEquals(Set.of("a", "owner", "balance", "audits"), names(ledger.getDeclaredFields()));
        assertEquals(Set.of("a", "clamp"), names(ledger.getDeclaredMethods()));
        var entry = types.get("fixtures.obf.Ledger$Entry");
        assertEquals(Set.of("amount"), names(entry.getDeclaredFields()));
        assertEquals(Set.of("a", "doubled"), names(entry.getDeclaredMethods()));
        var vault = types.get("fixtures.obf.Vault");
        assertEquals(Set.of("reads"), names(vault.getDeclaredFields()));
        assertEquals(Set.of("a", "b", "bump", "unmask"), names(vault.getDeclaredMethods()));
        assertEquals(Set.of("describe"), names(types.get("fixtures.obf.Main").getDeclaredMethods()));
    }

    @Test void optimizedProguardInlineFramesAreSkippedNotApplied() throws Exception {
        Path result = rename("obf8-opt");
        String report = Files.readString(result.resolve("rename.json"));
        assertTrue(report.contains("\"applicable_classes\":3,\"applicable_members\":6,\"inline_frames_ignored\":0"), report);
        // ProGuard writes inline frames without a class qualifier; clamp/bump frames match no method and are skipped.
        assertTrue(report.contains("\"skipped\":{\"MEMBER_NOT_FOUND\":3,\"NOT_PRIVATE\":10}"), report);
        assertTrue(report.contains("{\"reason\":\"MEMBER_NOT_FOUND\",\"rule\":\"method fixtures/obf/a#a -> clamp\"}"), report);
        assertTrue(report.contains("{\"reason\":\"NOT_PRIVATE\",\"rule\":\"method fixtures/obf/b#a -> doubled\"}"), report);

        var types = link(classes(result.resolve("renamed.jar")));
        assertEquals(Set.of("owner", "balance", "audits"), names(types.get("fixtures.obf.Ledger").getDeclaredFields()));
        assertEquals(Set.of("a"), names(types.get("fixtures.obf.Ledger").getDeclaredMethods()));
        assertEquals(Set.of("a"), names(types.get("fixtures.obf.Ledger$Entry").getDeclaredMethods()));
        assertEquals(Set.of("a", "b", "unmask"), names(types.get("fixtures.obf.Vault").getDeclaredMethods()));
    }

    @Test void stringDecryptorFoldsMaskedLiteralsAfterNamesAreRestored() throws Exception {
        for (String variant : List.of("obf8", "obf8-opt")) {
            Path renamed = rename(variant).resolve("renamed.jar");
            Path result = directory.resolve(variant + "-transformed");
            assertEquals(0, run("transform", renamed.toString(), "--passes", "string-decryptor,integer-branches", "--output", result.toString()), errors.toString());
            String report = Files.readString(result.resolve("transform.json"));
            assertTrue(report.contains("\"status\":\"OUTPUT_VALIDATED\""), report);
            assertEquals(2, report.split("\"pass\":\"string-decryptor-v1\"", -1).length - 1, report);
            assertFalse(report.contains("\"pass\":\"integer-branches-v2\""), "javac already folds constant branches; ProGuard adds none");
            assertTrue(report.contains("\"class\":\"fixtures/obf/Vault\""), report);
            assertFalse(report.contains("ledger-ready"), "plaintext must not be logged");
            var transformed = classes(result.resolve("worker/transformed/transformed.jar"));
            assertDoesNotThrow(() -> link(transformed), variant);
            String constants = new String(transformed.get("fixtures.obf.Vault"), java.nio.charset.StandardCharsets.ISO_8859_1);
            assertTrue(constants.contains("ledger-ready") && constants.contains("audit trail"), variant);
        }
    }
}
